#include <stdio.h>

/* teste do desafio media-de-dois — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: a comparacao e por TEXTO (o %f do aluno, seis casas), nunca por
   igualdade de double. A captura acontece dentro do teste: freopen manda o
   stdout para um arquivo temporario proprio do cenario, fflush descarrega e o
   arquivo e lido de volta. O main e o relatorio sao do harness.
   As duas medias caem em .5 de proposito: sem o cast a divisao corta e as
   duas linhas saem erradas — o cenario nao passa com a conta inteira. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void mediaDeDois(void);

SM_TEST(as_duas_medias_com_a_metade) {
    freopen("sm_saida_1.tmp", "w", stdout);
    mediaDeDois();
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a media de 7 e 8", linha, "a media de 7 e 8 e 7.500000\n",
              "com a conta em real, 15 dividido por 2 da 7.5 — sem o cast sairia 7.000000");
    fgets(linha, 80, f);
    checa_str("a media de 10 e 3", linha, "a media de 10 e 3 e 6.500000\n",
              "com a conta em real, 13 dividido por 2 da 6.5 — sem o cast sairia 6.000000");
    fclose(f);
}

SM_TEST(a_saida_acaba_na_segunda_media) {
    freopen("sm_saida_2.tmp", "w", stdout);
    mediaDeDois();
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    fgets(linha, 80, f);
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda media: nenhuma linha extra e aceita");
    fclose(f);
}

